pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor) public {
        // Admissible domain: actor must be a usable address distinct from the
        // implicit zero owner so ownership transfer and the protected call are
        // meaningful.
        vm.assume(actor != address(0));

        // Initial owner is address(0); transfer ownership to the fuzzed actor
        // via the legitimate entry point.
        vm.prank(address(0));
        c.transferOwnership(actor);

        // Drive c through `owned` as the (now) legitimate owner. The call must
        // succeed and, per the reference contract, must be side-effect free
        // with respect to the owner state.
        vm.prank(actor);
        bool ok;
        try c.owned() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: for any admissible owner-actor, owned() succeeds and
        // leaves the observable owner state unchanged.
        assertTrue(ok && c.owner() == actor);
    }
}

